-- Charte des documents : défauts du schéma alignés sur la charte Kouzia (ambre #fe9a00, nuit #0b1020).
-- Redéfinition SQLite de CompanySettings (prisma migrate diff) : toutes les colonnes et toutes les lignes copiées,
-- aucune valeur existante réécrite ; seul le DEFAULT des deux couleurs change pour les lignes créées ensuite.
-- RedefineTables
PRAGMA defer_foreign_keys=ON;
PRAGMA foreign_keys=OFF;
CREATE TABLE "new_CompanySettings" (
    "id" TEXT NOT NULL PRIMARY KEY,
